values ('7e57c578-4d96-4343-a3f4-ba6cb3b4adf1', 'characters', 'jason-duval', 'CONFIRMED', '{"es":"Jason Duval"}'::jsonb, '{"es":"Personaje 001","en":"Character 001","pt":"Personagem 001","fr":"Personnage 001"}'::jsonb, '{"es":"Uno de los dos protagonistas de GTA VI, ligado a los Keys y arrastrado a una historia criminal junto a Lucia.","en":"One of GTA VI’s two protagonists, tied to the Keys and pulled into a crime story alongside Lucia.","pt":"Um dos dois protagonistas de GTA VI, ligado aos Keys e arrastado para uma história criminosa ao lado de Lucia.","fr":"L’un des deux protagonistes de GTA VI, lié aux Keys et entraîné dans une histoire criminelle aux côtés de Lucia."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar explica que Jason creció rodeado de estafadores y delincuentes, pasó un tiempo en el ejército y después trabajó para traficantes locales en los Keys."}]},{"type":"paragraph","content":[{"type":"text","text":"Su encuentro con Lucia se convierte en el eje de la historia."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar says Jason grew up around grifters and crooks, spent time in the Army and later worked for local drug runners in the Keys."}]},{"type":"paragraph","content":[{"type":"text","text":"Meeting Lucia becomes the pivot of the story."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar conta que Jason cresceu rodeado de vigaristas e criminosos, passou pelo exército e depois trabalhou para traficantes locais nos Keys."}]},{"type":"paragraph","content":[{"type":"text","text":"O encontro com Lucia torna-se o eixo da história."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selon Rockstar, Jason a grandi entouré d’escrocs et de voyous, est passé par l’armée puis a travaillé pour des trafiquants locaux dans les Keys."}]},{"type":"paragraph","content":[{"type":"text","text":"Sa rencontre avec Lucia devient le pivot de l’histoire."}]}]}}'::jsonb, '{"es":"Jason quiere una vida sencilla, pero las cosas no dejan de complicarse.","en":"Jason wants an easy life, but things just keep getting harder.","pt":"Jason quer uma vida simples, mas as coisas não param de complicar.","fr":"Jason veut une vie simple, mais tout ne cesse de se compliquer."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Jason_Duval_01.07m377xeb6jhq.jpg?akim=1&imdensity=1&imwidth=3840', 'Jason Duval', null, array['character','protagonist','keys']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, true, 0, '{}'::jsonb)
