values ('67d62125-5e16-4ef1-a55e-79aa6b15ab86', 'characters', 'lucia-caminos', 'CONFIRMED', '{"es":"Lucia Caminos"}'::jsonb, '{"es":"Personaje 002","en":"Character 002","pt":"Personagem 002","fr":"Personnage 002"}'::jsonb, '{"es":"La segunda protagonista de GTA VI: recién salida de prisión y decidida a cambiar las reglas del juego.","en":"GTA VI’s second protagonist: fresh out of prison and determined to change the odds.","pt":"A segunda protagonista de GTA VI: acabada de sair da prisão e decidida a mudar as regras do jogo.","fr":"La seconde protagoniste de GTA VI : tout juste sortie de prison et décidée à changer la donne."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Según Rockstar, la lucha de Lucia por su familia terminó llevándola a prisión en Leonida."}]},{"type":"paragraph","content":[{"type":"text","text":"Tras salir, está decidida a cambiar sus circunstancias, y Jason pasa a ser una pieza central de ese plan."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar says Lucia’s fight for her family landed her in prison in Leonida."}]},{"type":"paragraph","content":[{"type":"text","text":"Now out, she is set on changing her circumstances — and Jason becomes central to that plan."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Segundo a Rockstar, a luta de Lucia pela família acabou por levá-la à prisão em Leonida."}]},{"type":"paragraph","content":[{"type":"text","text":"Depois de sair, está decidida a mudar a sua situação, e Jason torna-se peça central desse plano."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selon Rockstar, le combat de Lucia pour sa famille l’a menée en prison à Leonida."}]},{"type":"paragraph","content":[{"type":"text","text":"Libérée, elle est déterminée à changer sa situation, et Jason devient la pièce centrale de ce plan."}]}]}}'::jsonb, '{"es":"El padre de Lucia le enseñó a pelear desde que empezó a caminar.","en":"Lucia’s father taught her to fight as soon as she could walk.","pt":"O pai de Lucia ensinou-a a lutar desde que começou a andar.","fr":"Le père de Lucia lui a appris à se battre dès qu’elle a su marcher."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Jason_and_Lucia_01_landscape.12x2gvspcm_3m.jpg?akim=1&imdensity=1&imwidth=3840', 'Lucia Caminos', null, array['character','protagonist']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, true, 1, '{}'::jsonb)
