values ('f4e0a0dd-582a-4db4-a317-4efaf0985a0f', 'characters', 'cal-hampton', 'CONFIRMED', '{"es":"Cal Hampton"}'::jsonb, '{"es":"Personaje 003","en":"Character 003","pt":"Personagem 003","fr":"Personnage 003"}'::jsonb, '{"es":"Amigo de Jason y socio de Brian, obsesionado con las comunicaciones de la Guardia Costera.","en":"Jason’s friend and Brian’s associate, with an ear glued to Coast Guard radio chatter.","pt":"Amigo de Jason e sócio de Brian, obcecado com as comunicações da Guarda Costeira.","fr":"Ami de Jason et associé de Brian, l’oreille collée aux communications des garde-côtes."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describe a Cal como amigo de Jason y socio de Brian. Pasa el tiempo en casa escuchando las comunicaciones de la Guardia Costera y cultivando una paranoia casi rutinaria."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describes Cal as Jason’s friend and a fellow associate of Brian. He spends his time at home snooping on Coast Guard communications and embracing casual paranoia."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar descreve Cal como amigo de Jason e sócio de Brian. Passa o tempo em casa a escutar as comunicações da Guarda Costeira, com uma paranoia quase rotineira."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar décrit Cal comme l’ami de Jason et un associé de Brian. Il passe son temps chez lui à espionner les communications des garde-côtes, dans une paranoïa presque routinière."}]}]}}'::jsonb, '{"es":"¿Y si todo lo que hay en internet fuera verdad?","en":"What if everything on the internet was true?","pt":"E se tudo o que está na internet fosse verdade?","fr":"Et si tout ce qu’on lit sur internet était vrai ?"}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Cal_Hampton_landscape.17k7bnt3myg.2.jpg?akim=1&imdensity=1&imwidth=3840', 'Cal Hampton', null, array['character']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 2, '{}'::jsonb)
