values ('c3888fa8-8629-47d4-ab05-21e162252b3b', 'characters', 'boobie-ike', 'CONFIRMED', '{"es":"Boobie Ike"}'::jsonb, '{"es":"Personaje 004","en":"Character 004","pt":"Personagem 004","fr":"Personnage 004"}'::jsonb, '{"es":"Leyenda local de Vice City con un imperio legal de inmuebles, un club y un estudio de grabación.","en":"A Vice City local legend whose legitimate empire spans real estate, a club and a recording studio.","pt":"Lenda local de Vice City com um império legal de imóveis, um clube e um estúdio de gravação.","fr":"Légende locale de Vice City, à la tête d’un empire légal : immobilier, un club et un studio."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar presenta a Boobie como una leyenda de Vice City que levantó un imperio entre inmuebles, un club y un estudio de grabación. Trabaja con Dre’Quan en Only Raw Records."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar presents Boobie as a Vice City legend who built an empire across real estate, a club and a recording studio. He partners with Dre’Quan on Only Raw Records."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar apresenta Boobie como uma lenda de Vice City que construiu um império entre imóveis, um clube e um estúdio. Trabalha com Dre’Quan na Only Raw Records."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar présente Boobie comme une légende de Vice City qui a bâti un empire entre immobilier, club et studio d’enregistrement. Il s’associe à Dre’Quan sur Only Raw Records."}]}]}}'::jsonb, '{"es":"Todo es cuestión de corazón: el Jack of Hearts.","en":"It’s all about heart — the Jack of Hearts.","pt":"É tudo uma questão de coração: o Jack of Hearts.","fr":"Tout est une question de cœur : le Jack of Hearts."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Boobie_Ike_landscape.0ldnbn87k-8mq.jpg?akim=1&imdensity=1&imwidth=3840', 'Boobie Ike', null, array['character','vice city','only raw']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 3, '{}'::jsonb)
