values ('1019e896-ed1a-42aa-a1eb-0e356fe6d1c2', 'characters', 'drequan-priest', 'CONFIRMED', '{"es":"Dre’Quan Priest"}'::jsonb, '{"es":"Personaje 005","en":"Character 005","pt":"Personagem 005","fr":"Personnage 005"}'::jsonb, '{"es":"Aspirante a magnate musical que intenta pasar del trapicheo callejero a la escena de Vice City.","en":"An aspiring music mogul trying to move from street hustling into the Vice City scene.","pt":"Aspirante a magnata da música que tenta passar do negócio de rua para a cena de Vice City.","fr":"Aspirant magnat de la musique qui tente de passer de la débrouille de rue à la scène de Vice City."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar dice que Dre’Quan era más buscavidas que gánster y que siempre quiso entrar en la música. Ficha a Real Dimez para Only Raw Records mientras se abre camino en la escena local."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar says Dre’Quan was always more hustler than gangster and always wanted to break into music. He signs Real Dimez to Only Raw Records as he works the local scene."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar diz que Dre’Quan sempre foi mais desenrascado do que gangster e sempre quis entrar na música. Contrata as Real Dimez para a Only Raw Records."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selon Rockstar, Dre’Quan a toujours été plus débrouillard que gangster et rêvait de musique. Il signe Real Dimez chez Only Raw Records."}]}]}}'::jsonb, '{"es":"Only Raw… Records","en":"Only Raw… Records","pt":"Only Raw… Records","fr":"Only Raw… Records"}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/DreQuan_Priest_landscape.0_b7hszyze6cy.jpg?akim=1&imdensity=1&imwidth=3840', 'Dre’Quan Priest', null, array['character','music','only raw']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 4, '{}'::jsonb)
