values ('480e8ac1-67dd-4e49-a0e5-b15169c25148', 'characters', 'real-dimez', 'CONFIRMED', '{"es":"Real Dimez"}'::jsonb, '{"es":"Personaje 006","en":"Character 006","pt":"Personagem 006","fr":"Personnage 006"}'::jsonb, '{"es":"Bae-Luxe y Roxy, un dúo que convierte el trapicheo local en dinero y fama a golpe de música y redes.","en":"Bae-Luxe and Roxy, a duo turning local hustle into money and notoriety through music and social media.","pt":"Bae-Luxe e Roxy, uma dupla que transforma o negócio local em dinheiro e fama com música e redes sociais.","fr":"Bae-Luxe et Roxy, un duo qui transforme la débrouille locale en argent et notoriété grâce à la musique et aux réseaux."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describe a Real Dimez como amigas desde el instituto que construyeron una audiencia con temas de rap y redes sociales antes de fichar por Only Raw Records."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describes Real Dimez as friends since high school who built a following with rap tracks and social media before signing to Only Raw Records."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar descreve as Real Dimez como amigas desde o secundário que conquistaram público com rap e redes sociais antes de assinar pela Only Raw Records."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar décrit Real Dimez comme deux amies depuis le lycée qui ont bâti une audience avec du rap et les réseaux sociaux avant de signer chez Only Raw Records."}]}]}}'::jsonb, '{"es":"Vídeos virales. Hooks virales.","en":"Viral videos. Viral hooks.","pt":"Vídeos virais. Refrões virais.","fr":"Vidéos virales. Refrains viraux."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Real_Dimez_landscape.0637akp_a5a_q.jpg?akim=1&imdensity=1&imwidth=3840', 'Real Dimez', null, array['character','music','social media']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 5, '{}'::jsonb)
