values ('cf6f1844-e7a9-4fc8-a044-e3fa91ba3396', 'characters', 'raul-bautista', 'CONFIRMED', '{"es":"Raul Bautista"}'::jsonb, '{"es":"Personaje 007","en":"Character 007","pt":"Personagem 007","fr":"Personnage 007"}'::jsonb, '{"es":"Un atracador de bancos veterano que siempre busca gente dispuesta a asumir más riesgos.","en":"A seasoned bank robber always looking for people willing to take bigger risks.","pt":"Um assaltante de bancos veterano sempre à procura de quem aceite correr mais riscos.","fr":"Un braqueur de banques chevronné, toujours en quête de partenaires prêts à prendre plus de risques."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describe a Raul como un atracador seguro de sí mismo, carismático y astuto, cuyo apetito por el riesgo no deja de subir las apuestas."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describes Raul as a confident, charming and cunning bank robber whose appetite for risk keeps raising the stakes."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar descreve Raul como um assaltante confiante, carismático e astuto, cujo apetite pelo risco não para de subir a parada."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar décrit Raul comme un braqueur sûr de lui, charmeur et rusé, dont l’appétit du risque fait sans cesse monter les enjeux."}]}]}}'::jsonb, '{"es":"La experiencia cuenta.","en":"Experience counts.","pt":"A experiência conta.","fr":"L’expérience compte."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Raul_Bautista_landscape.11_3hd0fr69~j.jpg?akim=1&imdensity=1&imwidth=3840', 'Raul Bautista', null, array['character','heists']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 6, '{}'::jsonb)
