values ('5a3c5141-c911-4b4d-a935-7ae063a5781e', 'characters', 'brian-heder', 'CONFIRMED', '{"es":"Brian Heder"}'::jsonb, '{"es":"Personaje 008","en":"Character 008","pt":"Personagem 008","fr":"Personnage 008"}'::jsonb, '{"es":"Traficante de la vieja escuela de los Keys que sigue moviendo mercancía desde su astillero.","en":"An old-school Keys drug runner still moving product through his boat yard.","pt":"Traficante da velha guarda dos Keys que continua a movimentar mercadoria a partir do seu estaleiro.","fr":"Trafiquant de la vieille école des Keys qui écoule toujours sa marchandise depuis son chantier naval."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describe a Brian como un veterano de la época del contrabando en los Keys. Jason vive gratis en una de sus propiedades a cambio de ayudar con las extorsiones locales."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describes Brian as a veteran of the Keys’ smuggling era. Jason lives rent-free at one of his properties in exchange for help with local shakedowns."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar descreve Brian como um veterano da era do contrabando nos Keys. Jason vive de graça numa das suas propriedades em troca de ajuda com extorsões locais."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar décrit Brian comme un vétéran de l’époque de la contrebande dans les Keys. Jason loge gratuitement chez lui en échange de coups de main pour des extorsions locales."}]}]}}'::jsonb, '{"es":"No hay nada mejor que un Mudslide al atardecer.","en":"Nothing better than a Mudslide at sunset.","pt":"Nada melhor do que um Mudslide ao pôr do sol.","fr":"Rien de mieux qu’un Mudslide au coucher du soleil."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Brian_Heder_landscape.0a-egj5b8yo1q.jpg?akim=1&imdensity=1&imwidth=3840', 'Brian Heder', null, array['character','keys','boat yard']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, false, 7, '{}'::jsonb)
