values ('e43da822-24f4-4612-ac32-affa7698ab9e', 'locations', 'vice-city', 'CONFIRMED', '{"es":"Vice City"}'::jsonb, '{"es":"Lugar 001","en":"Location 001","pt":"Local 001","fr":"Lieu 001"}'::jsonb, '{"es":"La ciudad bañada en neón en el centro del regreso de GTA VI a la Vice City actual.","en":"The neon-soaked city at the heart of GTA VI’s return to modern-day Vice City.","pt":"A cidade banhada em néon no centro do regresso de GTA VI à Vice City atual.","fr":"La ville baignée de néons au cœur du retour de GTA VI dans la Vice City d’aujourd’hui."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar presenta GTA VI como un regreso a la Vice City contemporánea, dentro del estado ficticio de Leonida."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar frames GTA VI as a return to modern-day Vice City, inside the fictional state of Leonida."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar apresenta GTA VI como um regresso à Vice City contemporânea, dentro do estado fictício de Leonida."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar présente GTA VI comme un retour dans la Vice City contemporaine, au sein de l’État fictif de Leonida."}]}]}}'::jsonb, '{"es":"Vice City, USA.","en":"Vice City, USA.","pt":"Vice City, USA.","fr":"Vice City, USA."}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Vice_City_10.0f1q-xa_4q8r2.jpg?akim=1&imdensity=1&imwidth=3840', 'Vice City', null, array['location','vice city','leonida']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, true, 8, '{"map":{"x":71,"y":64}}'::jsonb)
