values ('2565a352-9454-46b2-a708-96e4a44b17b8', 'locations', 'state-of-leonida', 'CONFIRMED', '{"es":"Estado de Leonida","en":"State of Leonida","pt":"Estado de Leonida","fr":"État de Leonida"}'::jsonb, '{"es":"Lugar 002","en":"Location 002","pt":"Local 002","fr":"Lieu 002"}'::jsonb, '{"es":"El estado ficticio por el que se extiende la conspiración criminal del juego.","en":"The fictional state across which the game’s criminal conspiracy stretches.","pt":"O estado fictício por onde se estende a conspiração criminosa do jogo.","fr":"L’État fictif sur lequel s’étend la conspiration criminelle du jeu."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La descripción oficial del juego sitúa la conspiración a lo largo del estado de Leonida, con Vice City como gran escenario urbano."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The official game description says the conspiracy stretches across the state of Leonida, with Vice City as the central urban setting."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A descrição oficial do jogo situa a conspiração ao longo do estado de Leonida, com Vice City como grande cenário urbano."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La description officielle du jeu situe la conspiration à travers l’État de Leonida, Vice City en étant le décor urbain central."}]}]}}'::jsonb, '{}'::jsonb, null, null, null, array['location','leonida']::text[], 'c40c0a82-fbeb-4afd-a3c1-79448fbf21e6', true, false, 9, '{"map":{"x":44,"y":34}}'::jsonb)
