values ('eec95ca7-1c76-4ce8-abee-c2c0130cc2a4', 'locations', 'leonida-keys', 'OBSERVED', '{"es":"Leonida Keys"}'::jsonb, '{"es":"Lugar 003","en":"Location 003","pt":"Local 003","fr":"Lieu 003"}'::jsonb, '{"es":"Los Keys, donde Jason trabaja para traficantes locales y Brian gestiona un astillero.","en":"The Keys, where Jason works for local drug runners and Brian runs a boat yard.","pt":"Os Keys, onde Jason trabalha para traficantes locais e Brian gere um estaleiro.","fr":"Les Keys, où Jason travaille pour des trafiquants locaux et où Brian tient un chantier naval."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El material oficial de personajes sitúa a Jason y a Brian en los Keys, lo que convierte la zona en uno de los lugares más recurrentes del material previo al lanzamiento."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar’s official character material places Jason and Brian in the Keys, making the region one of the clearest recurring locations in the pre-release material."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O material oficial de personagens coloca Jason e Brian nos Keys, tornando a zona um dos locais mais recorrentes do material de pré-lançamento."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Le matériel officiel sur les personnages place Jason et Brian dans les Keys, ce qui fait de la région l’un des lieux les plus récurrents avant la sortie."}]}]}}'::jsonb, '{}'::jsonb, 'https://www.rockstargames.com/VI/_next/static/media/Leonida_Keys_06.0eapr3hbeyewx.jpg?akim=1&imdensity=1&imwidth=3840', 'Leonida Keys', null, array['location','keys']::text[], '7c3c6b80-fe81-44a5-ad62-9daecd4de75f', true, true, 10, '{"map":{"x":52,"y":88}}'::jsonb)
