values ('8530868b-43c1-476c-abdb-26007ae4ccfa', 'facts', 'physical-code-in-box', 'CONFIRMED', '{"es":"La versión física es un código en caja","en":"The physical version is code-in-box","pt":"A versão física é um código na caixa","fr":"La version physique est un code en boîte"}'::jsonb, '{"es":"Dato verificado","en":"Verified fact","pt":"Dado verificado","fr":"Donnée vérifiée"}'::jsonb, '{"es":"La caja incluye un código de descarga; no habrá disco.","en":"The box contains a download code; there is no disc.","pt":"A caixa inclui um código de descarga; não haverá disco.","fr":"La boîte contient un code de téléchargement ; pas de disque."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Según el soporte oficial, la edición física contiene un código de descarga para permitir la precarga y no incluye disco."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Official support says the physical edition contains a download code to allow pre-loading and does not include a disc."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Segundo o suporte oficial, a edição física contém um código de descarga para permitir o pré-carregamento e não inclui disco."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selon l’assistance officielle, l’édition physique contient un code de téléchargement pour le préchargement et n’inclut pas de disque."}]}]}}'::jsonb, '{}'::jsonb, null, null, null, array['fact','physical']::text[], 'b2f41701-6879-4974-a695-931643789b57', true, false, 28, '{}'::jsonb)
