insert into public.articles (id, slug, title, excerpt, body, category_id, tags, cover_image, cover_alt, cover_caption, author_name, source_id, evidence, published, published_at, featured)
values ('f1f1c36f-cf8f-44ab-a4ae-fda1771449a1', 'rockstar-anuncia-gta-vi-the-album', '{"es":"Rockstar anuncia GTA VI: The Album","en":"Rockstar announces GTA VI: The Album","pt":"Rockstar anuncia GTA VI: The Album","fr":"Rockstar annonce GTA VI: The Album"}'::jsonb, '{"es":"Treinta y cuatro canciones originales acompañarán el lanzamiento del 19 de noviembre. Seis sencillos ya están disponibles.","en":"Thirty-four original songs will accompany the November 19 launch. Six singles are already out.","pt":"Trinta e quatro músicas originais vão acompanhar o lançamento de 19 de novembro. Seis singles já estão disponíveis.","fr":"Trente-quatre titres originaux accompagneront la sortie du 19 novembre. Six singles sont déjà disponibles."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar anunció el 17 de septiembre de 2026 GTA VI: The Album, una colección de 34 canciones originales que se publicará el 19 de noviembre, el mismo día que el juego."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Seis sencillos para abrir boca"}]},{"type":"paragraph","content":[{"type":"text","text":"El anuncio llegó acompañado de seis sencillos disponibles desde ese mismo día. Es la primera vez que la música de Leonida se presenta como un proyecto propio, separado de la banda sonora de las radios."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"La música siempre ha sido media ciudad en Vice City."}]}]},{"type":"paragraph","content":[{"type":"text","text":"En el archivo, el álbum queda registrado como dato confirmado y enlazado a su fuente oficial en Newswire."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On September 17, 2026 Rockstar announced GTA VI: The Album, a collection of 34 original songs releasing November 19 — the same day as the game."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Six singles to start"}]},{"type":"paragraph","content":[{"type":"text","text":"The announcement came with six singles available the same day. It is the first time Leonida’s music has been framed as a standalone project, separate from the in-game radio."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"In Vice City, music has always been half the city."}]}]},{"type":"paragraph","content":[{"type":"text","text":"In the archive, the album is logged as a confirmed fact and linked to its official Newswire source."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 17 de setembro de 2026 a Rockstar anunciou GTA VI: The Album, uma coleção de 34 músicas originais que chega a 19 de novembro, com o jogo."}]},{"type":"paragraph","content":[{"type":"text","text":"O anúncio trouxe seis singles disponíveis no mesmo dia."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Le 17 septembre 2026, Rockstar a annoncé GTA VI: The Album, 34 titres originaux disponibles le 19 novembre, le jour de la sortie du jeu."}]},{"type":"paragraph","content":[{"type":"text","text":"L’annonce s’accompagne de six singles disponibles le jour même."}]}]}}'::jsonb, (select id from public.categories where slug = 'musica'), array['música','álbum','oficial']::text[], 'https://www.rockstargames.com/VI/_next/static/media/The_Album_Cover_Art_landscape.000ifb9a.j-gp.jpg?akim=1&imdensity=1&imwidth=3840', 'Rockstar anuncia GTA VI: The Album', 'Portada de GTA VI: The Album. Imagen: Rockstar Games.', 'Redacción Leonida Records', '66a5b314-2051-417e-afb6-8f0fa85abe4d', 'CONFIRMED', true, '2026-09-17T16:00:00Z', true)
