values ('75db133c-ac24-43bd-a3d6-c9d1b3c06ff1', 'an-extended-look-ya-disponible', '{"es":"An Extended Look ya está disponible","en":"An Extended Look is out now","pt":"An Extended Look já está disponível","fr":"An Extended Look est disponible"}'::jsonb, '{"es":"Veintiséis minutos de GTA VI capturados íntegramente con metraje del juego en PlayStation 5.","en":"Twenty-six minutes of GTA VI captured entirely from in-game footage on PlayStation 5.","pt":"Vinte e seis minutos de GTA VI capturados integralmente com imagens do jogo na PlayStation 5.","fr":"Vingt-six minutes de GTA VI capturées intégralement en jeu sur PlayStation 5."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar publicó el 27 de agosto de 2026 Grand Theft Auto VI: An Extended Look, una presentación larga capturada íntegramente con metraje del juego en PlayStation 5."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Qué cambia para el archivo"}]},{"type":"paragraph","content":[{"type":"text","text":"Cada plano del vídeo es una fuente potencial. Los datos observados en él se registran con su marca de tiempo y quedan separados de la especulación."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On August 27, 2026 Rockstar released Grand Theft Auto VI: An Extended Look, a long-form presentation captured entirely from in-game footage on PlayStation 5."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What it means for the archive"}]},{"type":"paragraph","content":[{"type":"text","text":"Every shot is a potential source. Facts observed in it are logged with a timestamp and kept apart from speculation."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 27 de agosto de 2026 a Rockstar publicou Grand Theft Auto VI: An Extended Look, capturado integralmente com imagens do jogo na PlayStation 5."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Le 27 août 2026, Rockstar a publié Grand Theft Auto VI: An Extended Look, capturé intégralement en jeu sur PlayStation 5."}]}]}}'::jsonb, (select id from public.categories where slug = 'trailers'), array['vídeo','ps5','oficial']::text[], 'https://www.rockstargames.com/VI/_next/static/media/Jason_and_Lucia_Motel_landscape.08edvuwtm-20v.jpg?akim=1&imdensity=1&imwidth=3840', 'An Extended Look ya está disponible', 'Jason y Lucia. Imagen: Rockstar Games.', 'Redacción Leonida Records', '898d22ed-2e86-4aa7-a3eb-8b5c46216f16', 'CONFIRMED', true, '2026-08-27T15:00:00Z', false)
