values ('6651d6e9-1ea4-4759-ad82-870d8652ebf1', 'abiertas-las-reservas-de-gta-vi', '{"es":"Abiertas las reservas de GTA VI","en":"GTA VI pre-orders are open","pt":"As pré-reservas de GTA VI estão abertas","fr":"Les précommandes de GTA VI sont ouvertes"}'::jsonb, '{"es":"Rockstar abre las reservas, confirma la experiencia para un jugador y detalla el paquete Vintage Vice City.","en":"Rockstar opens pre-orders, confirms a single-player experience and details the Vintage Vice City Pack.","pt":"A Rockstar abre as pré-reservas, confirma a experiência para um jogador e detalha o Vintage Vice City Pack.","fr":"Rockstar ouvre les précommandes, confirme une expérience solo et détaille le Vintage Vice City Pack."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El anuncio oficial del 24 de junio de 2026 abrió las reservas de GTA VI y detalló el paquete Vintage Vice City junto con otras ventajas de reserva."}]},{"type":"paragraph","content":[{"type":"text","text":"En el mismo texto, Rockstar describe el juego como una experiencia para un jugador."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar’s official June 24, 2026 announcement opened GTA VI pre-orders and detailed the Vintage Vice City Pack alongside other pre-order benefits."}]},{"type":"paragraph","content":[{"type":"text","text":"In the same post, Rockstar describes the game as a single-player experience."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O anúncio oficial de 24 de junho de 2026 abriu as pré-reservas de GTA VI e detalhou o Vintage Vice City Pack."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L’annonce officielle du 24 juin 2026 a ouvert les précommandes de GTA VI et détaillé le Vintage Vice City Pack."}]}]}}'::jsonb, (select id from public.categories where slug = 'lanzamiento'), array['reservas','ediciones','oficial']::text[], 'https://www.rockstargames.com/VI/_next/static/media/Official_Cover_Art_landscape.12.uu2irr.2_a.jpg?akim=1&imdensity=1&imwidth=3840', 'Abiertas las reservas de GTA VI', 'Portada oficial de GTA VI. Imagen: Rockstar Games.', 'Redacción Leonida Records', '81f73204-b4d4-4e14-a9eb-6cf75df68bdf', 'CONFIRMED', true, '2026-06-24T14:00:00Z', false)
