values ('313728dc-7039-43f8-a5fa-627cdb807532', 'trailer-2-llega', '{"es":"El Tráiler 2 llega con 2:47 de GTA VI","en":"Trailer 2 lands with 2:47 of GTA VI","pt":"O Trailer 2 chega com 2:47 de GTA VI","fr":"La bande-annonce 2 dévoile 2:47 de GTA VI"}'::jsonb, '{"es":"El segundo tráiler amplía la historia de Jason y Lucia y el mundo de Leonida.","en":"The second trailer expands the story of Jason and Lucia and the world of Leonida.","pt":"O segundo trailer amplia a história de Jason e Lucia e o mundo de Leonida.","fr":"La deuxième bande-annonce approfondit l’histoire de Jason et Lucia et le monde de Leonida."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar publicó el Tráiler 2 el 6 de mayo de 2025. La biblioteca oficial lo identifica como una pieza de 2 minutos y 47 segundos."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar released Trailer 2 on May 6, 2025. The official library lists it as a 2 minute 47 second piece."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Rockstar publicou o Trailer 2 a 6 de maio de 2025, com 2 minutos e 47 segundos."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar a publié la bande-annonce 2 le 6 mai 2025 : 2 minutes et 47 secondes."}]}]}}'::jsonb, (select id from public.categories where slug = 'trailers'), array['tráiler','oficial']::text[], 'https://www.rockstargames.com/VI/_next/static/media/Jason_and_Lucia_01_landscape.12x2gvspcm_3m.jpg?akim=1&imdensity=1&imwidth=3840', 'El Tráiler 2 llega con 2:47 de GTA VI', 'Jason y Lucia. Imagen: Rockstar Games.', 'Redacción Leonida Records', 'e246a6b7-7431-4d7d-afaa-c9aa66da1ad8', 'CONFIRMED', true, '2025-05-06T15:00:00Z', false)
