values ('cd37112c-6849-445c-a536-fe5cc899f949', 'primer-trailer-presenta-vice-city', '{"es":"El primer tráiler presenta la Vice City moderna","en":"The first trailer introduces modern Vice City","pt":"O primeiro trailer apresenta a Vice City moderna","fr":"La première bande-annonce dévoile la Vice City moderne"}'::jsonb, '{"es":"La primera revelación oficial presenta Vice City, a Jason, a Lucia y el estado de Leonida.","en":"The first official reveal introduces Vice City, Jason, Lucia and the state of Leonida.","pt":"A primeira revelação oficial apresenta Vice City, Jason, Lucia e o estado de Leonida.","fr":"La première révélation officielle présente Vice City, Jason, Lucia et l’État de Leonida."}'::jsonb, '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El primer tráiler oficial de GTA VI se publicó el 4 de diciembre de 2023 y abrió la etapa pública de información sobre el juego."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first official GTA VI trailer was released on December 4, 2023, opening the game’s public information era."}]}]},"pt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O primeiro trailer oficial de GTA VI foi publicado a 4 de dezembro de 2023."}]}]},"fr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La première bande-annonce officielle de GTA VI a été publiée le 4 décembre 2023."}]}]}}'::jsonb, (select id from public.categories where slug = 'trailers'), array['tráiler','oficial']::text[], 'https://www.rockstargames.com/VI/_next/static/media/Jason_Duval_01.07m377xeb6jhq.jpg?akim=1&imdensity=1&imwidth=3840', 'El primer tráiler presenta la Vice City moderna', 'Jason Duval. Imagen: Rockstar Games.', 'Redacción Leonida Records', 'e246a6b7-7431-4d7d-afaa-c9aa66da1ad8', 'CONFIRMED', true, '2023-12-04T23:00:00Z', false)
